/* =========================================================
   재정경제부 시사경제퀴즈(2025-08-29) OX 109문항 시드

   화면 정책이 OX·2지선다이므로 원본 200문항 중 OX 109문항만 넣는다.
   객관식 91문항은 선택지를 임의로 줄이지 않고, 별도 검수 후 추가한다.
   ========================================================= */

/*
   JSON 원문을 MySQL COMPRESS 형식으로 압축해 마이그레이션 파일 크기를 줄였다.
   JSON_TABLE은 MySQL 8 이상에서 지원한다.
 */
SET @quiz_seed_json = CONVERT(
    UNCOMPRESS(FROM_BASE64(''))
    USING utf8mb4
);

INSERT INTO `quiz_questions` (
    `question`,
    `explanation`,
    `quiz_type`,
    `active`
)
SELECT
    `question`,
    `explanation`,
    'OX',
    TRUE
FROM JSON_TABLE(
    @quiz_seed_json,
    '$[*]' COLUMNS (
        `question` TEXT PATH '$.question',
        `explanation` TEXT PATH '$.explanation',
        `answer` CHAR(1) PATH '$.answer'
    )
) AS `seed`;

SET @first_seeded_quiz_question_id = LAST_INSERT_ID();

INSERT INTO `quiz_choices` (
    `question_id`,
    `content`,
    `is_correct`
)
SELECT
    @first_seeded_quiz_question_id + `seed`.`ordinality` - 1,
    'O',
    `seed`.`answer` = 'O'
FROM JSON_TABLE(
    @quiz_seed_json,
    '$[*]' COLUMNS (
        `ordinality` FOR ORDINALITY,
        `answer` CHAR(1) PATH '$.answer'
    )
) AS `seed`
UNION ALL
SELECT
    @first_seeded_quiz_question_id + `seed`.`ordinality` - 1,
    'X',
    `seed`.`answer` = 'X'
FROM JSON_TABLE(
    @quiz_seed_json,
    '$[*]' COLUMNS (
        `ordinality` FOR ORDINALITY,
        `answer` CHAR(1) PATH '$.answer'
    )
) AS `seed`;

SET @quiz_seed_json = NULL;
SET @first_seeded_quiz_question_id = NULL;
